// Physical hardware model generated by hardware_model.py; see that module for the facts.
import modelData from "./data/hardware-model.json";

interface ModelSlot {
  id: string;
  accepts: string[];
  srsim?: string | number;
  types?: string[];
}

interface ModelPart {
  kind: string;
  slots?: ModelSlot[];
  occupies?: string[];
  label?: string;
}

interface ModelChassis {
  slots: ModelSlot[];
  exclusive?: string[][];
  integrated?: string;
}

export interface HardwareIssue {
  code: string;
  path: string;
  message: string;
}

type Item = Record<string, unknown>;

const parts = modelData.parts as Record<string, ModelPart>;
const chassisModels = modelData.chassis as Record<string, ModelChassis>;

const items = (value: unknown): Item[] =>
  Array.isArray(value) ? value.filter((item): item is Item => typeof item === "object" && item !== null) : [];
const slotText = (value: unknown) => (value === undefined || value === null ? "" : String(value).trim());
const srsimSlots = (slots: ModelSlot[] = []) => slots.map((slot) => String(slot.srsim));

/** SR-SIM component slots for line cards; [] when the chassis is not modelled or is integrated. */
export function lineCardSlots(chassis: string): number[] {
  const model = chassisModels[chassis];
  if (!model || model.integrated) return [];
  return model.slots.flatMap((slot) => (typeof slot.srsim === "number" ? [slot.srsim] : []));
}

/** Module slots of an XCM or integrated card; [] when the model does not know the card. */
export function moduleSlots(cardType: string | undefined): number[] {
  const part = parts[cardType ?? ""];
  if (!part || !["xcm", "cpm"].includes(part.kind)) return [];
  return (part.slots ?? []).map((slot) => Number(slot.srsim));
}

/** MDA slots of an IOM; [] when the model does not know the IOM. */
export function iomMdaSlots(iomType: string | undefined): number[] {
  const part = parts[iomType ?? ""];
  return part?.kind === "iom" ? (part.slots ?? []).map((slot) => Number(slot.srsim)) : [];
}

function moduleIssues(part: ModelPart, partType: string, component: Item, path: string): HardwareIssue[] {
  const issues: HardwareIssue[] = [];
  const modules = srsimSlots(part.slots);
  for (const key of ["mda", "xiom"] as const) {
    for (const item of items(component[key])) {
      const slot = slotText(item.slot);
      if (slot && !modules.includes(slot)) {
        issues.push({
          code: "module-slot",
          path: `${path}.${key}[${slot}]`,
          message: `${partType} has module slot${modules.length > 1 ? "s" : ""} ${[...modules].sort().join(", ")}, not ${slot}`
        });
      }
    }
  }
  const direct = new Set(items(component.mda).map((item) => slotText(item.slot)));
  const shared = items(component.xiom)
    .map((item) => slotText(item.slot))
    .filter((slot) => slot && direct.has(slot))
    .sort();
  for (const slot of new Set(shared)) {
    issues.push({ code: "module-taken", path: `${path}.xiom[${slot}]`, message: `module slot ${slot} holds either an XMA or an IOM, not both` });
  }
  for (const xiom of items(component.xiom)) {
    const iomType = String(xiom.type ?? "");
    const iom = parts[iomType];
    if (iom?.kind !== "iom") continue;
    const mdaSlots = srsimSlots(iom.slots);
    for (const mda of items(xiom.mda)) {
      const slot = slotText(mda.slot);
      if (slot && !mdaSlots.includes(slot)) {
        issues.push({
          code: "mda-slot",
          path: `${path}.xiom[${slotText(xiom.slot)}].mda[${slot}]`,
          message: `${iomType} has MDA slots ${[...mdaSlots].sort().join(", ")}, not ${slot}`
        });
      }
    }
  }
  return issues;
}

function carrierFit(carrier: ModelPart, cpms: Item[], used: Set<string>): "fits" | "occupied" | "mismatch" {
  for (const cpm of cpms) {
    const slot = (carrier.slots ?? []).find((candidate) => String(candidate.srsim) === slotText(cpm.slot).toUpperCase());
    const type = String(cpm.type ?? "");
    if (!slot || (type && !(slot.types ?? []).includes(type))) return "mismatch";
  }
  return (carrier.occupies ?? []).some((slotId) => used.has(slotId)) ? "occupied" : "fits";
}

function cpmIssues(chassisId: string, chassis: ModelChassis, cpms: Item[], used: Map<string, string>): HardwareIssue[] {
  const carrierSlot = chassis.slots.find((slot) => slot.accepts.includes("cma"));
  if (!carrierSlot) {
    const cpmSlots = chassis.slots.filter((slot) => slot.accepts.includes("cpm")).map((slot) => String(slot.srsim));
    return cpms.flatMap((cpm) => {
      const slot = slotText(cpm.slot).toUpperCase();
      return cpmSlots.includes(slot)
        ? []
        : [{ code: "no-such-slot", path: slot, message: `${chassisId} has CPM slots ${[...cpmSlots].sort().join(", ")}, not ${slot}` }];
    });
  }

  const carriers = (carrierSlot.types ?? []).map((type) => ({ type, part: parts[type] }));
  const fit = carriers.map(({ part }) => carrierFit(part, cpms, new Set(used.keys())));
  if (fit.includes("fits")) return [];
  const blocked = carriers.find((_, index) => fit[index] === "occupied");
  if (blocked) {
    const taken = (blocked.part.occupies ?? []).flatMap((slotId) => (used.has(slotId) ? [used.get(slotId) as string] : [])).join(", ");
    return [
      {
        code: "occupied",
        path: taken,
        message: `these CPMs need the ${blocked.part.label ?? blocked.type}, which also takes line-card slot ${taken}`
      }
    ];
  }
  const options = carriers.map(({ type, part }) => part.label ?? type).join("; ");
  return [{ code: "cpm-carrier", path: cpms.map((cpm) => slotText(cpm.slot)).join(","), message: `no CPM adapter fits these CPMs (${options})` }];
}

/** Problems that make a component list impossible in hardware; [] for chassis without a model. */
export function hardwareIssues(chassisId: string, components: unknown[]): HardwareIssue[] {
  const chassis = chassisModels[chassisId.trim().toLowerCase()];
  if (!chassis) return [];
  const all = items(components);

  if (chassis.integrated) {
    const card = parts[chassis.integrated];
    return all.flatMap((component) => moduleIssues(card, chassis.integrated as string, component, "A"));
  }

  const issues: HardwareIssue[] = [];
  const lineSlots = new Map(
    chassis.slots.filter((slot) => slot.srsim !== undefined && !slot.accepts.includes("cpm")).map((slot) => [String(slot.srsim), slot])
  );
  const cpms = all.filter((item) => /^[A-Za-z]$/.test(slotText(item.slot)));
  const used = new Map<string, string>();
  const lineTypes = new Set<string>();
  for (const card of all.filter((item) => !cpms.includes(item))) {
    const slotValue = slotText(card.slot);
    const slot = lineSlots.get(slotValue);
    if (!slot) {
      issues.push({
        code: "no-such-slot",
        path: slotValue,
        message: `${chassisId} has line-card slots 1 to ${lineSlots.size}, not ${slotValue || "(none)"}`
      });
      continue;
    }
    used.set(slot.id, slotValue);
    const type = String(card.type ?? "");
    const part = parts[type];
    if (!part) continue;
    lineTypes.add(type);
    if (!slot.accepts.includes(part.kind)) {
      issues.push({ code: "slot-kind", path: slotValue, message: `slot ${slotValue} takes ${slot.accepts.join("/")}, not ${type}` });
      continue;
    }
    issues.push(...moduleIssues(part, type, card, slotValue));
  }

  issues.push(...cpmIssues(chassisId, chassis, cpms, used));
  for (const group of chassis.exclusive ?? []) {
    const mixed = group.filter((type) => lineTypes.has(type)).sort();
    if (mixed.length > 1) {
      issues.push({ code: "mixed-types", path: "", message: `${mixed.join(" and ")} cannot be installed in the same chassis` });
    }
  }
  return issues;
}
